@js:
var r = result, n = 0;
Array.from(r, (x, i) => {
	var name = x.text(),
	link = x.attr("href");
	dir = {text: name, href: link,
	toString: function(){
		return JSON.stringify(this)}
	};
	if(/javascript/i.test(x) && (a = r[i + 1]) ){
		msg = "目录缺失，尝试修复中，稍等！";
		n += 1; n < 2 && java.log(msg);
		 //java.toast(msg)
			var ah = a.attr("href"), 
			url = /^https?/.test(ah) ? 
			ah : book.origin + ah;
			var h = java.ajax(url);
			path = "text.上一@href";
		u = java.getString(path, h);
		dir.href = u;
		//java.log(dir.toString())
		}
	return dir
	});

